config.customCSS:
@import url("https://use.typekit.net/aiw8vtw.css");


/*/ Font - you can change this by finding a font to import on Google Fonts /*/

@import url("https://use.typekit.net/aiw8vtw.css");

m {
font-family: anton, sans-serif;
  letter-spacing: 0.03em;
  font-size: 1em;
}

body {
  font-family: acumin-pro, sans-serif;
}

b {
  color:var(--main-color);
}
sb {
  color:var(--accent-color); 
  font-weight:bold;
}


h4 {
  font-size: 0.9em;
}

ft {
  background: var(--accent-color);
  padding-left: 0.4em;
    padding-right: 0.4em;
  padding-top: 0.2em;
    padding-bottom: 0.2em;

  color: var(--text-color)
}

fti {
    background: var(--text-color);
  padding-left: 0.4em;
    padding-right: 0.4em;
  padding-top: 0.2em;
    padding-bottom: 0.2em;
}

/* Main Colors - Add your primary, accent and text colors. You can also use hex color codes i.e #FF0000 */

:root{
  --main-color:#085748;
  --accent-color:#FF0619;
  --text-color:#FFFFFF;
}

/* The complicated stuff you don’t need to touch. */
.btn.btn-muted.btn-done.text-ellipsis {
background: url(https://media.edapp.com/image/upload/v1654666896/ringo-uploads/6124efd5975dff6d62262342/courseware/lessons/62a0367a1646103e1a10e85b/j1nvuxth6xyvth6uymvw.png) no-repeat;
 background-size: contain;
 color: var(--accent-color);
 box-shadow:none;
 line-height: .7em;
 transition: none;
 padding-right: 1em;
}
.btn.btn-muted.btn-done.text-ellipsis:hover, .btn.btn-muted.btn-done.text-ellipsis.__active {
 box-shadow:none;
 transform:none;
 background-image: url(https://media.edapp.com/image/upload/v1644305426/ringo-uploads/5f92779cffb6c20001de934f/courseware/lessons/615d7ed4d75fa3a3804ca390/up5s0oait5hxkvvfuajj.png);
  background-size: contain;
  background-repeat: no-repeat;
  color: var(--text-color);
  padding-right: 1em;
}
.btn.btn-muted, .btn.btn-solid {
  background:var(--main-color);
  color:var(--text-color); 
  border-radius:3px;
  transition: all ease-in-out 300ms;
  box-shadow: 0px 17px 10px -10px rgba(0,0,0,0.4);
}
.btn.btn-muted.__active, .btn.btn-muted:hover, .btn.btn-solid.__active, .btn.btn-solid:hover {
  background: var(--accent-color); 
  color:var(--text-color);
  transition-delay:0.25s;
  transition:all ease-in-out 300ms;
  box-shadow:0px 17px 10px -10px rgba(0,0,0,0.4);
  transform: translate(0px, -3px);
}


/*/ Header & Slides /*/
#lesson-header {
  background:white;
box-shadow: 0px 3px 8px 0px rgba(0,0,0,0.3);
}

#lesson-header-nav, .scroll-middle #lesson-header-nav, .scroll-bottom #lesson-header-nav {
  background: url(https://media.edapp.com/image/upload/v1644305426/ringo-uploads/5f92779cffb6c20001de934f/courseware/lessons/615d7ed4d75fa3a3804ca390/up5s0oait5hxkvvfuajj.png);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 8em;

}
#lesson-header-nav-menu-btn {
  border-left: 1.5px solid var(--text-color);
}
#lesson-header-title-content {
  border-bottom:0px solid var(--main-color);
  color:var(--main-color); 
}
#indicator { 
  background-color:var(--main-color); 
  color:var(--accent-color);
}
#slides {
  border-bottom: 0px solid var(--main-color);
}
#text-input-view #text-input-dismiss-btn {
  color:var(--main-color);
} 
#text-input-view #text-input-container-top {
  color:var(--main-color);
}
li::marker {
  color:var(--accent-color); 
}
hr {
  color:var(--accent-color);
}
.pswp__item {
    background:var(--main-color);
}
.selectable.active .btn { 
background-color: var(--accent-color);
}


/*/Templates/*/
.slide-image-slider .style-dark .caption-content {
  background:var(--main-color);
  color:var(--text-color);
  border-radius:3px;
}
.slide-image-slider .style-light .caption-content {  
  background:var(--accent-color);
  color:var(--text-color);
  border-radius:3px;
}
.slide-image-slider .btn-down, .slide-image-slider .btn-up {
  background:var(--main-color);
  color: var(--text-color);
  border-radius:50%;
}
.slide-image-slider .btn-down:hover,.slide-image-slider .btn-down:active, .slide-image-slider .btn-up:hover, .slide-image-slider .btn-up:active {
  background:var(--accent-color);  
  color: var(--text-color); 
  border-radius:50%;
}
.slide-image-gallery .pagination .dot {
 background-image: url(https://media.edapp.com/image/upload/v1644223193/ringo-uploads/5f92779cffb6c20001de934f/courseware/lessons/615d7ed4d75fa3a3804ca390/jhopbmvtu4dayxb8qj9a.png);
 background-size:cover;
 width:20px;
 height:20px;
 border: 0px solid;
}
.slide-image-gallery .pagination .dot.active {
 background-image: url(https://media.edapp.com/image/upload/v1644223190/ringo-uploads/5f92779cffb6c20001de934f/courseware/lessons/615d7ed4d75fa3a3804ca390/imstvtgvd3bkebaccvld.png);
 background-size:cover;
 width:20px;
 height:20px;
 border: 0px solid;
}
.slide-image-collection .tappy{ 
  transition: transform .5s ease;
}
.slide-image-collection .tappy:hover {
 transform: scale(1.1);
}
.slide-text-sequence .btn-down, .slide-text-sequence .btn-up {
  background:var(--main-color);
  color: var(--text-color);
  border-radius:50%;
}
.slide-text-sequence .btn-down:hover,.slide-text-sequence .btn-down:active, .slide-text-sequence .btn-up:hover, .slide-text-sequence .btn-up:active {
  background:var(--accent-color);  
  color: var(--text-color); 
  border-radius:50%;
}
.slide-reveal .btn-reveal-title.flippable {
  background:var(--accent-color);
  color: var(--text-color); 
} 
.slide-reveal .btn-reveal.active .btn-reveal-desc.flippable {
  background:var(--main-color);
  color: var(--text-color); 
}
.slide-reveal .btn-reveal-desc, .slide-reveal .btn-reveal-title {
  pointer-events:none;
}
.slide-expandable-list .item.active .item-button {
  background:var(--accent-color);  
  color: var(--text-color); 
}
.slide-image-waypoints .prev-wp, .slide-image-waypoints .next-wp{ 
  background:var(--main-color);
  color: var(--text-color);
}
.slide-list ::marker {
  color:var(--accent-color); 
}
.slide-speech-bubble .quote.quote-dk .quote-bg, .quote.quote-dk {
   background:var(--main-color);  
   color: var(--text-color); 
   opacity: 1;
}
.slide-speech-bubble .quote.pull-left.quote-dk:after {
    border-color: var(--main-color) transparent transparent;
}
.slide-comparison .slider-knob {
    background-color:var(--main-color);
}
.slide-comparison .slider-knob:before, .slide-comparison .slider-knob:after {
   background-color:var(--main-color);
}
.slide-table .table-row:nth-child(odd) {
    border-radius:3px;
    background: var(--accent-color);
    color: var(--text-color);
}
.slide-table .table-row:nth-child(even) {
    border-radius:3px;
    background:var(--accent-color);
    color: var(--text-color); 
}

/*/Interactions/*/
.slide-chat .message--question {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-chat.show-msg-true .selectable {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-chat.show-msg-true .selectable.active {
  background: var(--main-color);
  color:var(--text-color);
}
.slide-chat.state-complete .chat-msg.incorrect {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-chat.state-complete .chat-msg.correct {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-chat .message--question:after {
  border-color:var(--main-color) transparent transparent;
}
.slide-chat .message--answer:after {
  border-color:var(--accent-color) transparent transparent;
}
.slide-categorise .direction-ltr .selectable .btn-long, .direction-ltr .draggy .btn-long {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-circle-the-answer .circle-box.active .circle-box-text, .text-dark .slide-circle-the-answer .circle-box.active .circle-box-text {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-multiple-choice-game .btn.btn-solid {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-multiple-choice-game .selectable.active .btn {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-multiple-choice-game.state-complete .selectable.incorrect .btn {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-multiple-choice-game.state-complete .selectable.correct .btn {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-connect .connect-box {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-connect .connect-box.complete {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-game-true-or-false .game-statement {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-game-image-word-match .btn-word {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-game-image-word-match .btn-word.__active {
  background:var(--accent-color);
  color:var(--text-color);
}
.slide-carousel .btn.btn-solid {
  background:var(--main-color);
  color:var(--text-color);
}
.slide-slider .slider-bar, .slide-slider-survey .slider-bar {
  background:var(--main-color);
}
.slide-slider.active .slider-knob-input, .active.slide-slider-survey .slider-knob-input {
  background:var(--accent-color);
}
.slide-free-text-survey .btn-prompt, .slide-free-text-contribution .btn-prompt {
  border-radius:50% !important;
}
